      description:
        "Починаючи з 3 рівня, ваша майстерність вершника стає очевидною. Ви маєте <a href=\"/rules/abilities#advantage-and-disadvantage--advantage-and-disadvantage\">перевагу</a> на ряткидки, які робите, щоб уникнути падіння зі своєї верхової тварини. Якщо ви падаєте зі своєї верхової тварини і спускаєтеся не більш як на 10 футів, то можете приземлитися на ноги, якщо не є <a href=\"/rules/conditions#condition-incapacitated\">Недієздатними</a>.\n\nЗрештою, сісти на істоту або спішитися з неї коштує вам лише 5 футів руху, а не половину вашої швидкості.",
