      description:
        "Починаючи з 7 рівня, ви можете тимчасово перенести свою свідомість у луну. Дією ви можете бачити очима своєї луни й чути її вухами. У цей час ви є <a href=\"/rules/conditions#condition-deafened\">Оглухлими</a> й <a href=\"/rules/conditions#condition-blinded\">Засліпленими</a>. Ви можете підтримувати цей ефект до 10 хвилин і можете завершити його будь-коли без витрати дії. Поки луна використовується в такий спосіб, вона може перебувати від вас на відстані до 1000 футів, не знищуючись.",
