        "На 18 рівні ви можете <a href=\"/rules/combat#order-of-combat--bonus-actions\">бонусною дією</a> створити дві луни за допомогою своєї риси Прояв луни, і ці луни можуть співіснувати. Якщо ви намагаєтеся створити третю луну, дві попередні знищуються. Усе, що ви можете робити з позиції однієї луни, можна робити й з позиції іншої.\n\nКрім того, коли ви кидаєте ініціативу і у вас не лишилося використань риси Виплеск втілення, ви відновлюєте одне її використання.",
