        "На 7 рівні ви опановуєте нові способи використання своїх телекинетичних здібностей:\n\n• **Псі-стрибок.** <a href=\"/rules/combat#order-of-combat--bonus-actions\">Бонусною дією</a> ви можете підштовхнути власне тіло силою розуму. Ви отримуєте швидкість польоту, рівну подвоєній вашій швидкості ходи, до кінця поточного ходу. Після використання цієї бонусної дії ви не можете використати її знову, доки не завершите короткий або тривалий відпочинок, якщо не витратите кубик пси-енергії, щоб використати її знову.\n• **Телекінетичний поштовх.** Коли ви завдаєте цілі шкоди своєю рисою Псі-удар, ви можете змусити ціль зробити ряткидок Сили з КС, що дорівнює 8 + ваш Бонус Майстерності + ваш модифікатор Інтелекту. Якщо ряткидок провалено, ви можете або збити ціль з ніг, або перемістити її на відстань до 10 футів у будь-якому напрямку по горизонталі.",
