      description:
        "На 10 рівні ви вчитеся спрямовувати божественну силу, щоб запалювати ревність в інших. <a href=\"/rules/combat#order-of-combat--bonus-actions\">Бонусною дією</a> ви вивільняєте бойовий клич, наповнений божественною енергією. До десяти інших істот на ваш вибір у межах 60 футів від вас, які можуть вас чути, отримують <a href=\"/rules/abilities#advantage-and-disadvantage--advantage-and-disadvantage\">перевагу</a> на кидки атаки й ряткидки до початку вашого наступного ходу.\n\nПісля використання цієї риси ви не можете використати її знову, доки не завершите тривалий відпочинок.",
