      description: `Починаючи з 2 рівня, ви можете використати свій Виклик божественності, щоб відганяти потойбічних істот.

Дією ви демонструєте свій священний символ, і один небожитель, елементаль, фея або злий дух на ваш вибір у межах 30 футів від вас повинен зробити ряткидок Мудрості, за умови, що істота може вас бачити або чути. Якщо істота провалює ряткидок, вона відвернена на 1 хвилину або доки не зазнає будь-якої шкоди.

Відвернена істота мусить у свої ходи намагатися відійти від вас якомога далі та не може добровільно завершити свій рух у просторі в межах 30 футів від вас. Вона також не може виконувати <a href="/rules/combat#reactions--reactions">реакції</a>. На свою дію вона може лише виконати <a href="/rules/combat#actions-in-combat--dash">дію Ривок</a> або спробувати звільнитися від ефекту, що заважає їй рухатися. Якщо їй нікуди рухатися, вона може виконати дію Ухилення.

Після досягнення 5 рівня, коли істота провалює ряткидок проти вашої риси Арканне відганяння, вона вигнана на 1 хвилину (як у заклятті <a href="/spell/1241">Вигнання [Banishment]</a>, без потреби в <a href="/rules/spellcasting#concentration-rules">концентрації</a>), якщо вона не перебуває на рідному плані й її показник небезпеки не перевищує поріг, зазначений у таблиці Арканного вигнання:

Рівень клірика  ПН вигнаних істот
5-й             1/2 або нижче
8-й             1 або нижче
11-й            2 або нижче
14-й            3 або нижче
17-й            4 або нижче`,
