      description:
        "На 14 рівні, поки ви у люті, перебування на 0 хітів не робить вас <a href=\"/rules/conditions#condition-unconscious\">Непритомним</a>. Ви все одно мусите робити ряткидки від смерті й зазнаєте звичайних наслідків отримання шкоди при 0 хітах. Проте якщо ви мали б померти через провалені ряткидки від смерті, ви не помираєте, доки ваша лють не закінчиться, і тоді помираєте лише якщо все ще маєте 0 хітів.",
