      description:
        "На 14 рівні ви можете Дією обрати істоту в 60 футах, яку бачите. Вона робить ряткидок Мудрості; при провалі вона зачарована або <a href=\"/rules/conditions#condition-frightened\">налякана</a> вами (ваш вибір) на до 1 хвилини. Поки триває, істота бачить ілюзорну сутінкову площину, навколишні істоти — тіні, а ви лишаєтесь єдиним чітким обʼєктом. Ефект закінчується, якщо ви чи ваші союзники завдаєте їй шкоди, або якщо ви припиняєте <a href=\"/rules/spellcasting#concentration-rules\">концентрацію</a> (як на заклятті). Після використання — до кінця короткого чи тривалого відпочинку.",
      displayType: [FeatureDisplayType.ACTION],
      limitedUsesPer: RestType.SHORT_REST,
      usesCount: 1,
