      description:
        "Починаючи з 6 рівня, ви можете звернутися до свого покровителя, щоб схилити долю на свій бік. Коли ви робите перевірку характеристики або ряткидок, ви можете використати цю рису, щоб додати до свого кидка 1к10. Ви можете зробити це після того, як побачите початковий результат кидка, але до того, як настануть будь-які наслідки цього кидка.\n\nСкориставшись цією рисою, ви не можете використати її знову, доки не завершите короткий або довгий відпочинок.",
