      description:
        "Починаючи з 14 рівня, коли ви влучаєте по істоті атакою, ви можете скористатися цією рисою, щоб миттєво провести ціль крізь Нижні плани. Істота зникає й мчить крізь кошмарний краєвид.\n\nНаприкінці вашого наступного ходу ціль повертається в простір, який займала раніше, або в найближчий незайнятий простір. Якщо ціль не є нечистю, вона отримує 10к10 психічної шкоди, оговтуючись від пережитого жаху.\n\nСкориставшись цією рисою, ви не можете використати її знову, доки не завершите довгий відпочинок.",
