      description:
        "Починаючи з 6 рівня, коли ви вбиваєте гуманоїда, ви можете змусити його дух піднятися з тіла у вигляді спектра; статистики цієї істоти беруться з бестіарію. Коли спектр зʼявляється, він отримує <a href=\"/rules/combat#making-an-attack--temporary-hit-points\">тимчасові хіти</a> в кількості, що дорівнює половині вашого рівня чорнокнижника. Кидайте для спектра ініціативу; у бою він ходить у власній черзі. Він підкоряється вашим усним наказам і додає ваш бонус майстерності до своїх кидків атаки. Спектр залишається з вами до завершення вашого наступного тривалого відпочинку; тоді він зникає у потойбіччі.\n\nСкориставшись цією рисою, ви не можете застосувати її знову, доки не завершите тривалий відпочинок.",
