      description:
        "На 14 рівні сяйлива життєва сила вашого покровителя може врятувати вас від смерті. Коли на початку вашого ходу ви робите ряткидок від смерті, ви можете натомість підвестися на ноги в спалаху сяйва. Ви відновлюєте хіти в кількості, що дорівнює половині вашого максимуму хітів. Потім підводитеся, якщо бажаєте, і кожна істота на ваш вибір у межах 30 футів від вас отримує променеву шкоду в кількості 2к8 + ваш модифікатор Харизми та сліпне до кінця поточного ходу. Скориставшись цією рисою, ви не можете застосувати її знову, доки не завершите тривалий відпочинок.",
      displayType: [FeatureDisplayType.PASSIVE],
      limitedUsesPer: RestType.LONG_REST,
      usesCount: 1,
