      description:
        "На 1 рівні <a href=\"/rules/combat#order-of-combat--bonus-actions\">бонусною дією</a> створюєте примарне щупальце в межах 60 футів. Одразу зробіть по істоті в 10 футах від щупальця кидок атаки: при влучанні ціль отримує 1к8 холодної шкоди, а її швидкість зменшується на 10 футів до початку вашого наступного ходу. Щупальце триває 1 хвилину; бонусною дією можете перемістити його на 30 футів і повторити атаку. Використань дорівнює вашому Бонусу Майстерності за тривалий відпочинок. Шкода зростає до 2к8 на 10 рівні.",
