      description:
        'На 10 рівні ви вивчаєте закляття <a href="/spell/1515">Чорні щупальця Еварда [Evard\'s Black Tentacles]</a>. Воно зараховується до списку заклять чорнокнижника для вас, але не враховується в кількість відомих заклять.\n\nРаз на день ви можете накласти його без витрати осередку заклять. Коли ви накладаєте це закляття завдяки цій рисі, ви отримуєте <a href="/rules/combat#making-an-attack--temporary-hit-points">тимчасові хіти</a> в кількості, що дорівнює вашому рівню чорнокнижника, і шкода не може порушити вашу <a href="/rules/spellcasting#concentration-rules">концентрацію</a> на цьому заклятті.\n\nВикориставши цю рису для накладання закляття, ви не зможете зробити це знову, доки не завершите тривалий відпочинок.',
