      shortDescription:
        "Дією телепортуєте себе й до 5 союзників у 30 фт у водойму, яку бачили в межах 1 милі; виринаєте в найближчих вільних клітинках.",
      description:
        "На 14 рівні ви можете магічно відкрити тимчасовий шлях крізь воду. Дією оберіть точку на водній поверхні, яку бачите, в межах 30 футів. У цій точці виникає стовп води, що підіймається на 5 футів і створює вир. Тоді ви та до пʼяти інших готових істот, яких бачите в межах 30 футів від виру, миттєво телепортуєтеся до водойми, яку ви бачили або відвідували раніше того ж плану існування і яка міститься в межах 1 милі від вас. Кожен із вас зʼявляється в незайнятому просторі в межах 30 футів від поверхні цієї води.\n\nСкориставшись цією рисою, ви не можете застосувати її знову, доки не завершите короткий або тривалий відпочинок.",
