      engName: "Psychic Defenses",
      shortDescription:
        "Опір психічній шкоді; перевага на ряткидки проти зачарування та наляканості.",
      description:
        "З 6 рівня ви маєте опір психічній шкоді та <a href=\"/rules/abilities#advantage-and-disadvantage--advantage-and-disadvantage\">перевагу</a> на ряткидки проти станів Зачарований і <a href=\"/rules/conditions#condition-frightened\">Наляканий</a>.",
      displayType: [FeatureDisplayType.PASSIVE],
