      name: "Викривлювальний імплозія",
      engName: "Warping Implosion",
      shortDescription:
        "Дією телепортуєтесь на 120 фт; усі створіння в 30 фт від місця, яке ви покинули, роблять ряткидок Сили: при провалі отримують 3к10 силової шкоди й притягуються до цієї точки, при успіху — половину шкоди й не рухаються. 1/ТВ або за 5 очок чародійства.",
      description:
        "На 18 рівні ви можете вивільнити свою аберантну силу як аномалію, що викривляє простір. Дією ви можете телепортуватися в незайнятий простір, який бачите в межах 120 футів від себе. Одразу після того як ви зникаєте, кожне створіння в межах 30 футів від простору, який ви залишили, має зробити рятівний кидок Сили проти СК ряткидку ваших заклять. У разі провалу створіння отримує 3к10 шкоди силовим полем і його тягне прямо до простору, який ви залишили; воно завершує рух у незайнятому просторі якомога ближче до вашого колишнього місця. У разі успіху створіння отримує половину цієї шкоди й не притягується.\n\nПісля використання цієї риси ви не можете скористатися нею знову, доки не завершите тривалий відпочинок, якщо тільки не витратите 5 очок чародійства, щоб використати її повторно.",
