      description:
        'Ви вивчаєте додаткові закляття, коли досягаєте певних рівнів у цьому класі, як показано в таблиці Заклять годинникової душі. Кожне з цих заклять вважається для вас закляттям чародія, але не зараховується до кількості відомих вам заклять чародія.\n\nЩоразу, коли ви отримуєте рівень чародія, можете замінити одне закляття, отримане завдяки цій рисі, іншим закляттям того самого рівня. Нове закляття має бути закляттям школи Захисту або Перетворення зі списку заклять чародія, чорнокнижника чи чарівника.\n\nЗакляття годинникової душі:\n• 1 рівень: <a href="/spell/1306">Тривога [Alarm]</a>, <a href="/spell/1337">Захист від зла й добра [Protection from Evil and Good]</a>.\n• 3 рівень: <a href="/spell/1259">Підтримка [Aid]</a>, <a href="/spell/1281">Мале відновлення [Lesser Restoration]</a>.\n• 5 рівень: <a href="/spell/1216">Розвіювання магії [Dispel Magic]</a>, <a href="/spell/1236">Захист від енергії [Protection from Energy]</a>.\n• 7 рівень: <a href="/spell/1184">Свобода рухів [Freedom of Movement]</a>, <a href="/spell/1448">Виклик конструкту [Summon Construct]</a>.\n• 9 рівень: <a href="/spell/1173">Більше відновлення [Greater Restoration]</a>, <a href="/spell/1142">Стіна енергії [Wall of Force]</a>.\n\nКрім того, звіртеся з таблицею Проявів порядку й оберіть або випадково визначте, як саме ваш звʼязок із порядком проявляється щоразу, коли ви накладаєте будь-яке своє закляття чародія.',
