      description:
        "Починаючи з 6 рівня, ви здобуваєте кращий контроль над фазами своєї місячної магії. <a href=\"/rules/combat#order-of-combat--bonus-actions\">Бонусною дією</a> ви можете витратити 1 очко чародійства, щоб змінити поточну фазу вашого Місячного втілення на іншу.\n\nТепер ви також можете по одному разу накладати без витрати чарослота одне закляття 1 рівня з кожної місячної фази з таблиці Місячних заклять, якщо ваша поточна фаза збігається з фазою цього закляття. Після такого накладання ви не можете знову накласти це фазове закляття в такий спосіб, доки не завершите тривалий відпочинок.",
