      description:
        "Починаючи з 14 рівня, сила місячної фази насичує все ваше єство. Поки ви перебуваєте в певній фазі Місячного втілення, ви також отримуєте повʼязану з нею перевагу:\n\n• **Повня.** <a href=\"/rules/combat#order-of-combat--bonus-actions\">Бонусною дією</a> ви можете почати випромінювати яскраве світло в радіусі 10 футів і тьмяне світло ще на 10 футів далі або ж погасити це світло. Крім того, ви й створіння на ваш вибір маєте <a href=\"/rules/abilities#advantage-and-disadvantage--advantage-and-disadvantage\">перевагу</a> на перевірки Інтелекту (Розслідування) та Мудрості (Уважність), перебуваючи в яскравому світлі, яке ви випромінюєте.\n• **Молодик.** Ви маєте перевагу на перевірки Спритності (Непомітність). Крім того, доки ви повністю перебуваєте в темряві, кидки атаки проти вас мають перешкоду.\n• **Серп місяця.** Ви маєте опір некротичній та променевій шкоді.",
