      description:
        "На 18 рівні <a href=\"/rules/combat#order-of-combat--bonus-actions\">бонусною дією</a> ви можете звернутися до особливої сили вашої поточної фази Місячного втілення. Або ж, як частину бонусної дії, яку ви використовуєте, щоб змінити свою місячну фазу завдяки рисі Зростання і спад, ви можете негайно застосувати силу тієї фази, в яку переходите:\n\n• **Повня.** Ви на мить випромінюєте місячне сяйво. Кожне створіння на ваш вибір у межах 30 футів від вас має досягти успіху на рятівному кидку Статури проти СК ряткидку ваших заклять, інакше буде <a href=\"/rules/conditions#condition-blinded\">засліплене</a> до кінця свого наступного ходу. Крім того, одне створіння на ваш вибір у цій зоні відновлює 3к8 хіт-поінтів.\n• **Молодик.** Ви на мить випромінюєте похмурий морок. Кожне створіння на ваш вибір у межах 30 футів від вас має досягти успіху на рятівному кидку Спритності проти СК ряткидку ваших заклять, інакше отримає 3к10 некротичної шкоди, а його швидкість зменшиться до 0 до кінця його наступного ходу. Крім того, ви стаєте <a href=\"/rules/conditions#condition-invisible\">невидимими</a> до кінця свого наступного ходу або до моменту, коли негайно після цього здійсните атаку чи накладете закляття.\n• **Серп місяця.** Ви можете магічно телепортуватися в незайнятий простір, який бачите в межах 60 футів від себе. Ви можете взяти з собою одну готову істоту, яку бачите в межах 5 футів від себе. Це створіння телепортується в незайнятий простір на ваш вибір, який ви бачите в межах 5 футів від простору вашого призначення. Крім того, ви й це створіння отримуєте опір усім видам шкоди до початку вашого наступного ходу.\n\nПісля того як ви використаєте одну з цих переваг бонусної дії, ви не можете скористатися саме цією перевагою знову, доки не завершите тривалий відпочинок, якщо тільки не витратите 5 очок чародійства, щоб застосувати її повторно.",
      displayType: [FeatureDisplayType.BONUSACTION],
      limitedUsesPer: RestType.LONG_REST,
      usesCount: 1,
      usesPoolKey: "SORCERY_POINTS",
      usePrice: 5,
