      description:
        "Починаючи з 18 рівня, <a href=\"/rules/combat#order-of-combat--bonus-actions\">бонусною дією</a> ви можете витратити 6 очок чародійства, щоб магічно набути тіньової форми. У цій формі ви маєте опір усім видам шкоди, окрім силової та променевої, і можете проходити крізь інших створінь та предмети, ніби це складна місцевість. Якщо ви завершуєте свій хід усередині предмета, вас виштовхує в найближчий вільний простір, і ви отримуєте 5 силової шкоди. Ваша тіньова форма триває 1 хвилину.",
      displayType: [FeatureDisplayType.BONUSACTION],
