      engName: "Storm Guide",
      shortDescription:
        "Дією зупиняєте дощ у сфері радіусом 20 футів навколо себе; бонусною дією щораунду можете змінювати напрямок вітру у сфері радіусом 100 футів, не змінюючи його швидкості.",
      description:
        "На 6 рівні ви здобуваєте здатність непомітно керувати погодою навколо себе.\n\nЯкщо йде дощ, ви можете дією змусити його припинитися в сфері радіусом 20 футів із центром на вас. Ви можете завершити цей ефект <a href=\"/rules/combat#order-of-combat--bonus-actions\">бонусною дією</a>.\n\nЯкщо дме вітер, ви можете бонусною дією в кожному раунді обирати напрямок, у якому він дме в сфері радіусом 100 футів із центром на вас. Вітер дме в обраному напрямку до кінця вашого наступного ходу. Ця риса не змінює швидкість вітру.",
