      description:
        "Починаючи з 14 рівня, коли по вас влучає ближня атака, ви можете <a href=\"/rules/combat#reactions--reactions\">реакцією</a> завдати нападнику блискавичної шкоди, що дорівнює вашому рівню чародія. Нападник також повинен зробити рятівний кидок Сили проти СК ряткидку ваших заклять чародія. У разі провалу його відштовхує по прямій лінії на відстань до 20 футів від вас.",
