      description:
        "Починаючи з 2 рівня, ви можете тимчасово змінити фізичні властивості одного немагічного предмета, перетворивши одну речовину на іншу. Ви виконуєте особливу алхімічну процедуру над одним предметом, цілком складеним із дерева, каменю (але не коштовного каміння), заліза, міді або срібла, перетворюючи його на інший із цих матеріалів. За кожні 10 хвилин, які ви витрачаєте на процедуру, ви можете перетворити до 1 кубічного фута матеріалу. Через 1 годину або доки ви не втратите <a href=\"/rules/spellcasting#concentration-rules\">концентрацію</a> (ніби концентруєтеся на заклятті), матеріал повертається до свого первісного стану.",
