      description: `На 10 рівні ви додаєте закляття <a href="/spell/1189">Перевтілення [Polymorph]</a> до своєї книги заклять, якщо його там ще немає. Ви можете накласти <a href="/spell/1189">Перевтілення [Polymorph]</a>, не витрачаючи чарослот. Коли ви робите це, ви можете націлити лише себе і перетворитися на звіра з рейтингом небезпеки 1 або нижче.

      Після того як ви накладете <a href="/spell/1189">Перевтілення [Polymorph]</a> у цей спосіб, ви не можете зробити цього знову, доки не завершите короткий або тривалий відпочинок, хоча й надалі можете накладати це закляття звичайним способом, витрачаючи доступний чарослот.`,
