      shortDescription:
        'Якщо вас зводять до 0 ХП або ви стаєте Недієздатні не добровільно, автоматично накладаєте <a href="/spell/1239">Зʼява тварин [Conjure Animals]</a> (4 звіра КР ≤2) без концентрації, 1/ТВ.',
      description:
        'Починаючи з 14 рівня, духи природи, з якими ви спілкуєтеся, захищають вас у мить найбільшої беззахисності. Якщо вас зводять до 0 хіт-поінтів або ви стаєте <a href="/rules/conditions#condition-incapacitated">недієздатними</a> всупереч своїй волі, ви негайно отримуєте переваги закляття <a href="/spell/1239">Зʼява тварин [Conjure Animals]</a>, наче воно було накладене коміркою 9 рівня. Воно прикликає чотирьох звірів на ваш вибір із показником небезпеки 2 або нижче. Прикликані звірі зʼявляються в межах 20 футів від вас. Якщо вони не отримують від вас наказів, вони захищають вас від шкоди й атакують ваших ворогів. Закляття триває 1 годину, не потребує <a href="/rules/spellcasting#concentration-rules">концентрації</a> або до того, як ви його відкинете (без потрібної дії).\n\nСкориставшись цією рисою, ви не можете зробити цього знову, доки не завершите тривалий відпочинок.',
