        "Дією ви можете використати свій Виклик божественності, щоб наситити одну зброю, яку тримаєте, позитивною енергією. На 1 хвилину ви додаєте свій модифікатор Харизми до кидків атаки, зроблених цією зброєю (мінімум +1). Зброя також випромінює яскраве світло в радіусі 20 футів і тьмяне світло ще на 20 футів далі. Якщо зброя ще не є магічною, вона стає магічною на час дії ефекту.\n\nВи можете завершити цей ефект у свій хід як частину будь-якої іншої дії. Ефект також завершується, якщо ви перестаєте тримати або нести цю зброю чи якщо втрачаєте свідомість.",
