      description:
        "На 20 рівні ви можете наділити себе легендами — правдивими чи перебільшеними — про власні великі подвиги. <a href=\"/rules/combat#order-of-combat--bonus-actions\">Бонусною дією</a> ви здобуваєте такі переваги на 1 хвилину:\n• Ви сповнені потойбічної величі й маєте <a href=\"/rules/abilities#advantage-and-disadvantage--advantage-and-disadvantage\">перевагу</a> на всі перевірки Харизми.\n• Один раз у кожен свій хід, коли ви робите атаку зброєю й промахуєтесь, ви можете змусити цю атаку влучити натомість.\n• Якщо ви провалюєте ряткидок, ви можете використати <a href=\"/rules/combat#reactions--reactions\">реакцію</a>, щоб перекинути його. Ви мусите використати новий результат.\n\nСкориставшись цією рисою, ви не можете зробити це знову, доки не завершите тривалий відпочинок, хіба що витратите комірку заклинання 5 рівня, щоб скористатися нею ще раз.",
