      description:
        "На 20 рівні ви проявляєте іскру божественної сили на захист смертних царств. <a href=\"/rules/combat#order-of-combat--bonus-actions\">Бонусною дією</a> ви здобуваєте такі переваги на 1 хвилину:\n• Ви отримуєте істинний зір у межах 120 футів.\n• Ви маєте <a href=\"/rules/abilities#advantage-and-disadvantage--advantage-and-disadvantage\">перевагу</a> на кидки атаки проти аберацій, небожителів, елементалів, фей і вилюдків.\n• Коли ви влучаєте по істоті кидком атаки й завдаєте їй шкоди, ви також можете змусити її зробити ряткидок Харизми проти СК ряткидка ваших заклинань. У разі провалу істота магічно виганяється до свого рідного плану існування, якщо зараз перебуває не там. У разі успіху цю істоту не можна вигнати цією рисою протягом наступних 24 годин.\n\nСкориставшись цією бонусною дією, ви не можете зробити це знову, доки не завершите тривалий відпочинок, хіба що витратите комірку заклинання 5 рівня, щоб скористатися нею ще раз.",
