      description:
        "На 3 рівні ви отримуєте темнозір 60 футів (якщо вже маєте — радіус зростає на 30 футів). Крім того, ви майстерно ховаєтесь від чужого погляду: якщо ви перебуваєте у темряві, ви <a href=\"/rules/conditions#condition-invisible\">невидимі</a> для будь-якої істоти, що покладається на темнозір, щоб бачити вас у цій темряві.",
