      description:
        'Починаючи з 3 рівня, коли ви досягаєте певних рівнів у цьому класі, ви вивчаєте додаткові заклинання, як показано в таблиці заклинань вбивці чудовиськ. Для вас кожне з них вважається заклинанням слідопита, але не зараховується до кількості відомих вам заклинань слідопита.\n\n3 рівень: <a href="/spell/1337">Захист від зла й добра [Protection from Evil and Good]</a>\n5 рівень: <a href="/spell/1287">Зона правди [Zone of Truth]</a>\n9 рівень: <a href="/spell/1231">Магічне коло [Magic Circle]</a>\n13 рівень: <a href="/spell/1202">Вигнання [Banishment]</a>\n17 рівень: <a href="/spell/1143">Стримування монстра [Hold Monster]</a>',
      displayType: [FeatureDisplayType.PASSIVE],
