      description:
        'Також на 3 рівні ви вивчаєте замовляння <a href="/spell/1352">Магічна рука [Mage Hand]</a>, якщо ще не знаєте його. Коли ви накладаєте його, рука набуває форми ваших ройових духів природи.\n\nВи також вивчаєте додаткове заклинання 1 рівня або вище, коли досягаєте певних рівнів у цьому класі, як показано в таблиці заклинань охоронця рою. Для вас кожне з них вважається заклинанням слідопита, але не зараховується до кількості відомих вам заклинань слідопита.\n\n3 рівень: <a href="/spell/1041">Вогники фей [Faerie fire]</a>, <a href="/spell/1352">Магічна рука [Mage Hand]</a>\n5 рівень: <a href="/spell/1273">Павутиння [Web]</a>\n9 рівень: <a href="/spell/1244">Газоподібна форма [Gaseous Form]</a>\n13 рівень: <a href="/spell/1205">Арканне око [Arcane eye]</a>\n17 рівень: <a href="/spell/1160">Нашестя комах [Insect Plague]</a>',
