      description:
        "На 3 рівні з вами поєднується рій невідчутних духів природи, який може допомагати вам у бою. Поки ви живі, рій лишається у вашому просторі, повзаючи по вас або пурхаючи й метушачись навколо вас у межах вашого простору. Ви самі визначаєте його вигляд або можете кинути к4 за таблицею зовнішності рою: 1 — рій комах, 2 — мініатюрні сучкуваті пагонці, 3 — пурхотливі птахи, 4 — грайливі піксі.\n\nОдин раз у кожен свій хід ви можете змусити рій допомогти вам одним із наведених способів безпосередньо після того, як ви влучаєте по істоті атакою:\n• Ціль атаки отримує 1к6 колючої шкоди від рою.\n• Ціль атаки мусить успішно пройти ряткидок Сили проти СК ряткидка ваших заклинань, інакше рій переміщує її на відстань до 15 футів горизонтально в напрямку на ваш вибір.\n• Рій переміщує вас на 5 футів горизонтально в напрямку на ваш вибір.",
