      shortDescription:
        "Ви вивчаєте два заклинання з будь-якого класу; вони стають для вас заклинаннями барда і не входять до ліміту відомих заклинань.",
      description:
        "На 6 рівні ви вивчаєте два заклинання на ваш вибір із будь-якого класу. Заклинання, яке ви обираєте, має бути рівня, який ви можете накладати, як показано в таблиці барда, або це може бути замовляння. Обрані заклинання вважаються для вас заклинаннями барда, але не зараховуються до кількості заклинань барда, які ви знаєте.",
      displayType: [FeatureDisplayType.PASSIVE],
