        "На 3 рівні ви обираєте особливий бойовий стиль. Оберіть один із наведених варіантів. Ви не можете взяти одну й ту саму опцію Бойового стилю більше одного разу, навіть якщо пізніше знову отримаєте право вибору.\n\n**Дуелянт.** Коли ви тримаєте рукопашну зброю в одній руці й не тримаєте іншої зброї, ви отримуєте бонус +2 до кидків шкоди цією зброєю.\n\n**Бій двома зброями.** Коли ви бʼєтеся двома зброями, ви можете додавати модифікатор характеристики до шкоди другої атаки.",
