      description:
        'Починаючи з 3-го рівня, щойно ви досягаєте певних рівнів у цьому класі, у вас завжди підготовлені деякі заклинання, як показано в таблиці Заклинань алхіміка. Ці заклинання вважаються для вас заклинаннями винахідника, але не враховуються до кількості заклинань винахідника, які ви готуєте.\n\n3 рівень: <a href="/spell/1303">Цілюще слово [healing word]</a>, <a href="/spell/1499">Промінь хвороби [Ray of Sickness]</a>\n5 рівень: <a href="/spell/1271">Палюча сфера [Flaming Sphere]</a>, <a href="/spell/1286">Кислотна стріла Мельфа [Melf\'s Acid arrow]</a>\n9 рівень: <a href="/spell/1244">Газоподібна форма [Gaseous Form]</a>, <a href="/spell/1230">Масове цілюще слово [Mass Healing Word]</a>\n13 рівень: <a href="/spell/1179">Усихання [Blight]</a>, <a href="/spell/1193">Захист від смерті [Death Ward]</a>\n17 рівень: <a href="/spell/1172">Вбивча хмара [Cloudkill]</a>, <a href="/spell/1157">Оживлення мерців [Raise Dead]</a>',
