      description:
        "Починаючи з 9-го рівня, кожна створена вами містична гармата стає руйнівнішою:\n\n* Усі кидки шкоди гармати збільшуються на 1к8.\n* Дією ви можете наказати гарматі здетонувати, якщо перебуваєте в межах 60 футів від неї. Це знищує гармату й змушує кожну істоту в межах 20 футів від неї здійснити ряткидок Спритності проти СК ряткидка ваших заклинань; у разі провалу істота зазнає 3к8 шкоди силовим полем, а в разі успіху — половину цієї шкоди.",
      displayType: [FeatureDisplayType.PASSIVE], // Adds capability
