      description:
        "До 13-го рівня ви достатньо добре розумієте принципи магії, щоб імпровізувати з використанням предметів, навіть якщо вони не призначені для вас. Ви ігноруєте всі вимоги до класу, раси й рівня під час використання магічних предметів.",
