      engName: "Thief's Reflexes",
      shortDescription: "Два ходи в першому раунді бою.",
      description:
        "Коли ви досягаєте 17-го рівня, ви стаєте майстром засідок і блискавичного уникнення небезпеки. Під час першого раунду будь-якого бою ви можете зробити два ходи. Перший хід ви робите на своїй звичайній ініціативі, а другий — на ініціативі, меншій на 10. Ви не можете використати цю рису, якщо ви захоплені зненацька.",
