      description:
        "Починаючи з 3-го рівня, ви стаєте найсмертоноснішими на початку бою. Ви маєте <a href=\"/rules/abilities#advantage-and-disadvantage--advantage-and-disadvantage\">перевагу</a> на кидки атаки проти будь-якої істоти, яка ще не зробила хід у поточному бою. Крім того, будь-яке влучання по істоті, яка здивована (surprised), є критичним влучанням.",
      displayType: [FeatureDisplayType.PASSIVE],
