      description:
        "На 13-му рівні ваші чуття майже неможливо обдурити. Дією ви відчуваєте присутність ілюзій, перевертнів, які не перебувають у своїй первісній формі, та іншої магії, покликаної ошукати чуття, у межах 30 футів від вас, за умови, що ви не <a href=\"/rules/conditions#condition-blinded\">засліплені</a> й не <a href=\"/rules/conditions#condition-deafened\">оглухлі</a>. Ви відчуваєте, що якийсь ефект намагається вас обманути, але не дізнаєтеся, що саме приховано чи яка його справжня природа.\n\nВи можете використати цю рису кількість разів, що дорівнює вашому модифікатору Мудрості (мінімум один раз), і відновлюєте всі витрачені використання, коли завершуєте довгий відпочинок.",
