      description:
        "Ваш шлях повʼязаний з особливим опануванням зброї. Ви здобуваєте такі переваги:\n\n**Зброя кенсея.** Оберіть два види зброї, які стануть для вас зброєю кенсея: одну рукопашну й одну дальнобійну. Кожна з них мусить бути простою або бойовою зброєю, що не має властивостей важка і особлива. Довгий лук також може бути вашою зброєю кенсея. Ви отримуєте володіння обраною зброєю, якщо ще не маєте його. Обрана зброя вважається для вас монашою. На 6, 11 і 17 рівнях ви обираєте ще по одному додатковому виду зброї — рукопашної або дальнобійної — який також стає для вас зброєю кенсея.\n\n**Шлях пензля.** Ви отримуєте володіння приладдям каліграфа або приладдям художника на свій вибір.\n\n**Спритне парирування.** Якщо у свій хід ви робите удар без зброї як частину <a href=\"/rules/combat#actions-in-combat--attack\">дії Атака</a> і тримаєте зброю кенсея ближнього бою, то отримуєте +2 до КЗ до початку свого наступного ходу, доки ця зброя залишається у вас в руках і ви не є <a href=\"/rules/conditions#condition-incapacitated\">недієздатним</a>.\n\n**Постріл кенсея.** <a href=\"/rules/combat#order-of-combat--bonus-actions\">Бонусною дією</a> ви можете посилити свої далекобійні атаки зброєю кенсея. Коли до кінця поточного ходу ви влучаєте дальньою атакою зброєю кенсея, ціль отримує додатково 1к4 шкоди того самого типу.",
